    37	function loadGoogleIdentityServices(): Promise<GoogleIdentityServices> {
    38	  gisLoad ??= new Promise<GoogleIdentityServices>((resolve, reject) => {
    39	    const existing = installedGis();
    40	    if (existing) {
    41	      resolve(existing);
    42	      return;
    43	    }
    44	    const script = document.createElement('script');
    45	    script.src = GIS_SRC;
    46	    script.async = true;
    47	    script.onload = () => {
    48	      const loaded = installedGis();
    49	      if (loaded) resolve(loaded);
    50	      else reject(new Error('google sign-in loaded but did not install'));
    51	    };
    52	    script.onerror = () => reject(new Error('google sign-in could not be loaded'));
