104	
105	      setPhase('handoff');
106	      handedOff = true;
107	      await onSigned(message, signature);
108	      setPicking(false);
109	    } catch (failure) {
110	      if (!handedOff) onRejected(rejectionOf(failure));
111	    } finally {
112	      // CipherBox needs the wallet for one signature, never a standing session.
113	      disconnect();
114	      setPhase('idle');
115	    }
116	  };
117	
118	  if (!picking) {
119	    return (
120	      <button
121	        ref={triggerRef}
122	        type="button"
123	        data-testid={trigger.testId}
124	        className="terminal-btn"
125	        onClick={() => {
126	          onRejected(null);
127	          setPicking(true);
128	        }}
129	        disabled={disabled}
130	        aria-label={trigger.ariaLabel}
131	      >
132	        {trigger.label}
133	      </button>
134	    );
135	  }
136	
137	  // EIP-6963 can announce the same wallet twice; one row per name.
138	  const unique = connectors.filter((c, i, all) => all.findIndex((x) => x.name === c.name) === i);
139	
140	  return (
141	    <div ref={picker} className="wallet-connector-list" role="group" aria-label="Available wallets">
142	      {busy ? (
143	        <div className="wallet-login-status" aria-live="polite">
144	          {phaseLabel[phase]}
145	        </div>
146	      ) : unique.length === 0 ? (
147	        <div className="wallet-no-providers">
148	          no wallets detected. install MetaMask or another browser wallet.
149	        </div>
150	      ) : (
151	        <>
152	          <div className="wallet-connector-header">// select wallet</div>
153	          {unique.map((connector) => (
154	            <button
155	              key={connector.uid}
156	              type="button"
157	              className="wallet-connector-option"
158	              onClick={() => void sign(connector)}
159	              disabled={busy}
160	              aria-label={`Connect with ${connector.name}`}
161	            >
162	              [{connector.name}]
163	            </button>
164	          ))}
165	        </>
166	      )}
167	      <button
168	        type="button"
169	        className="wallet-connector-cancel"
170	        onClick={() => {
171	          cancelled.current = true;
172	          setPicking(false);
173	        }}
174	        disabled={phase === 'handoff'}
175	        aria-label="Cancel wallet connection"
176	      >
177	        // cancel
178	      </button>
179	    </div>
180	  );
181	}
